/** Every known setting, in ascending key order. */
export const SETTINGS = [
  { key: 'log.file', type: 'string', default: '' },
  { key: 'log.level', type: 'enum', members: ['debug', 'info', 'warn', 'error'], default: 'info' },
  { key: 'log.rotate', type: 'boolean', default: 'true' },
  { key: 'retry.attempts', type: 'integer', default: '3' },
  { key: 'retry.backoff', type: 'duration', default: '250ms' },
  { key: 'server.host', type: 'string', default: 'localhost' },
  { key: 'server.port', type: 'integer', default: '8080' },
  { key: 'server.timeout', type: 'duration', default: '30s' },
  { key: 'server.tls', type: 'boolean', default: 'false' },
  { key: 'tags', type: 'list', default: '' },
]

const BY_KEY = new Map(SETTINGS.map(declared => [declared.key, declared]))

/**
 * The setting one key names, or undefined when the schema does not know it.
 * @param {string} key - the dotted setting key.
 * @returns {{key: string, type: string, members?: string[], default: string} | undefined} the setting.
 */
export function setting(key) {
  return BY_KEY.get(key)
}

/**
 * The environment variable name one setting travels under: `CONF_` followed by its key
 * uppercased with every `.` replaced by `_`.
 * @param {string} key - the dotted setting key.
 * @returns {string} the environment variable name.
 */
export function envName(key) {
  return `CONF_${key.toUpperCase().replace(/\./gu, '_')}`
}

const KEY_BY_ENV_NAME = new Map(SETTINGS.map(declared => [envName(declared.key), declared.key]))

/**
 * The setting key one environment variable name names, or undefined when it names none.
 * @param {string} name - the environment variable name, as written.
 * @returns {string | undefined} the dotted setting key.
 */
export function keyForEnvName(name) {
  return KEY_BY_ENV_NAME.get(name)
}

/** One value that does not fit its setting's declared type. */
export class TypeError_ extends Error {
  constructor(message) {
    super(message)
    this.name = 'TypeError_'
  }
}

const DURATION = /^([0-9]+)(ms|s|m|h)$/u
const DURATION_MS = { ms: 1, s: 1000, m: 60000, h: 3600000 }
const INTEGER = /^-?(0|[1-9][0-9]*)$/u

/**
 * Coerce one setting's raw text by its declared type, and render it back.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting.
 * @param {string} text - the raw text a layer wrote, or the schema default.
 * @returns {string} the rendered value.
 * @throws {TypeError_} when `text` does not fit the declared type.
 */
export function coerce(declared, text) {
  switch (declared.type) {
    case 'string':
      return text
    case 'integer':
      if (!INTEGER.test(text)) throw new TypeError_(`${declared.key} is not an integer: ${text}`)
      return text
    case 'boolean':
      if (text !== 'true' && text !== 'false') throw new TypeError_(`${declared.key} is not a boolean: ${text}`)
      return text
    case 'enum':
      if (!declared.members.includes(text)) {
        throw new TypeError_(`${declared.key} is not one of ${declared.members.join('|')}: ${text}`)
      }
      return text
    case 'duration': {
      const match = DURATION.exec(text)
      if (!match) throw new TypeError_(`${declared.key} is not a duration: ${text}`)
      return String(Number(match[1]) * DURATION_MS[match[2]])
    }
    case 'list': {
      if (text === '') return ''
      const items = text.split(',').map(item => item.trim())
      if (items.some(item => item === '')) throw new TypeError_(`${declared.key} has an empty item: ${text}`)
      const kept = []
      const seen = new Set()
      for (const item of items) {
        if (seen.has(item)) continue
        seen.add(item)
        kept.push(item)
      }
      return kept.join(',')
    }
    default:
      throw new Error(`unknown type ${declared.type}`)
  }
}
"}

