/** One refusal of an environment line, carrying the 1-based line and column it was read at. */
export class EnvError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {number} column - the 1-based column of the raw line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, column, message) {
    super(message)
    this.name = 'EnvError'
    this.line = line
    this.column = column
  }
}

/**
 * Parse the environment layer's text into the settings it names.
 * @param {string} text - the whole standard input text.
 * @returns {Map<string, {text: string, line: number, column: number}>} each dotted setting
 *   key's raw value, its 1-based line, and the 1-based column of the value itself.
 * @throws {EnvError} on the first line the grammar refuses.
 */
export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const values = new Map()
  const seen = new Set()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const split = trimmed.indexOf('=')
    if (split === -1) throw new EnvError(line, indent(raw), 'expected NAME=VALUE')
    const name = trimmed.slice(0, split).trim()
    if (name === '') throw new EnvError(line, indent(raw), 'expected a variable name')
    const key = keyForEnvName(name)
    if (key === undefined) throw new EnvError(line, indent(raw), `unknown environment variable ${name}`)
    if (seen.has(name)) throw new EnvError(line, indent(raw), `${name} is set twice`)
    seen.add(name)
    const text_ = trimmed.slice(split + 1).trim()
    values.set(key, { text: text_, line, column: valueColumn(raw, split) })
  }
  return values
}
"}

