/**
 * Merge named layers, later over earlier.
 * @param {readonly {name: string, values: Map<string, {text: string, line: number, column:
 *   number}>}[]} layers - the layers, weakest first.
 * @returns {Map<string, {text: string, line: number, column: number, layer: string}>} each key's
 *   winning value, tagged with the name of the layer that won it.
 */
export function merge(layers) {
  const merged = new Map()
  for (const layer of layers) {
    for (const [key, value] of layer.values) merged.set(key, { ...value, layer: layer.name })
  }
  return merged
}
"}

