import { existsSync, readFileSync } from 'node:fs'
import { EnvError, parse as parseEnv } from './env.js'
import { IniError, parse as parseIni } from './ini.js'
import { merge } from './layer.js'
import { TypeMismatch, SETTINGS, coerce, setting } from './schema.js'

const USAGE = 'usage: cli.js dump <file>|get <file> <key>|load <base> <site>|origin <base> <site>'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/**
 * One INI layer, refused at its own position when the grammar rejects it, and, when `strict`,
 * refused at the first key the schema does not know.
 */
function iniLayer(name, path, strict) {
  if (!existsSync(path)) return fail(`cannot read ${path}`)
  let values
  try {
    values = parseIni(readFileSync(path, 'utf8'))
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
  if (strict) {
    for (const [key, value] of values) {
      if (setting(key) === undefined) fail(`${path}:${value.line}:${value.column}: unknown setting ${key}`)
    }
  }
  return { name, values }
}

/** The environment layer, read from standard input and refused at its own position. */
function envLayer(name, text) {
  try {
    return { name, values: parseEnv(text) }
  } catch (error) {
    if (!(error instanceof EnvError)) throw error
    return fail(`<stdin>:${error.line}:${error.column}: ${error.message}`)
  }
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { dump: 2, get: 3, load: 3, origin: 3 }
if (argv.length !== arity[mode]) fail(USAGE)

const out = []

if (mode === 'dump' || mode === 'get') {
  const values = merge([iniLayer('file', argv[1], false)])
  const raw = key => (values.has(key) ? values.get(key).text : setting(key).default)
  if (mode === 'dump') {
    for (const declared of SETTINGS) out.push(`${declared.key}=${raw(declared.key)}`)
  } else {
    if (setting(argv[2]) === undefined) fail(`unknown setting ${argv[2]}`)
    out.push(raw(argv[2]))
  }
} else {
  const base = iniLayer('base', argv[1], true)
  const site = iniLayer('site', argv[2], true)
  const env = envLayer('env', readFileSync(0, 'utf8'))
  const merged = merge([base, site, env])
  const where = { base: argv[1], site: argv[2], env: '<stdin>' }

  if (mode === 'origin') {
    for (const declared of SETTINGS) {
      const entry = merged.get(declared.key)
      out.push(`${declared.key} ${entry ? entry.layer : 'default'}`)
    }
  } else {
    for (const declared of SETTINGS) {
      const entry = merged.get(declared.key)
      const text = entry ? entry.text : declared.default
      try {
        out.push(`${declared.key}=${coerce(declared, text)}`)
      } catch (error) {
        if (!(error instanceof TypeMismatch)) throw error
        fail(`${where[entry.layer]}:${entry.line}:${entry.column}: ${error.message}`)
      }
    }
  }
}

process.stdout.write(out.map(line => `${line}\n`).join(''))
"}

